// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address target) public {
        // Admissible domain: a positive, sendable amount and a target distinct from c and this test
        amount = bound(amount, 1, type(uint128).max);
        vm.assume(target != address(0));
        vm.assume(target != address(c));
        vm.assume(target != address(this));

        // Fund the contract so the value transfer is legitimately admissible
        vm.deal(address(c), amount);

        uint256 targetBefore = target.balance;

        // owner is msg.sender at construction, i.e. this test contract
        c.sendMoney(target, amount);

        uint256 targetAfter = target.balance;

        // General rule: the call forwards exactly `amount` wei to the target.
        // Reference C holds for every admissible input; the mutant sends 0,
        // so the target's balance never grows by `amount`.
        assertTrue(targetAfter - targetBefore == amount);
    }
}
